children.input:
{
  "project_id": "4643cc0564f44287aac3",
  "name": "enable_semantic_search_with_owner_rls",
  "query": "create extension if not exists vector with schema extensions;

alter table public.document_sections
  add column if not exists embedding extensions.vector(384);

alter table public.documents
  alter column owner_id set default auth.uid();

create index if not exists document_sections_embedding_hnsw_idx
  on public.document_sections using hnsw (embedding vector_cosine_ops)
  where embedding is not null;

create index if not exists document_sections_document_id_idx
  on public.document_sections (document_id);

alter table public.documents enable row level security;
alter table public.document_sections enable row level security;

 drop policy if exists "Users can view their own documents" on public.documents;
create policy "Users can view their own documents"
  on public.documents for select to authenticated
  using ((select auth.uid()) = owner_id);

 drop policy if exists "Users can create their own documents" on public.documents;
create policy "Users can create their own documents"
  on public.documents for insert to authenticated
  with check ((select auth.uid()) = owner_id);

 drop policy if exists "Users can update their own documents" on public.documents;
create policy "Users can update their own documents"
  on public.documents for update to authenticated
  using ((select auth.uid()) = owner_id)
  with check ((select auth.uid()) = owner_id);

 drop policy if exists "Users can delete their own documents" on public.documents;
create policy "Users can delete their own documents"
  on public.documents for delete to authenticated
  using ((select auth.uid()) = owner_id);

 drop policy if exists "Users can view sections in their own documents" on public.document_sections;
create policy "Users can view sections in their own documents"
  on public.document_sections for select to authenticated
  using (exists (
    select 1 from public.documents d
    where d.id = document_sections.document_id
      and d.owner_id = (select auth.uid())
  ));

 drop policy if exists "Users can create sections in their own documents" on public.document_sections;
create policy "Users can create sections in their own documents"
  on public.document_sections for insert to authenticated
  with check (exists (
    select 1 from public.documents d
    where d.id = document_sections.document_id
      and d.owner_id = (select auth.uid())
  ));

 drop policy if exists "Users can update sections in their own documents" on public.document_sections;
create policy "Users can update sections in their own documents"
  on public.document_sections for update to authenticated
  using (exists (
    select 1 from public.documents d
    where d.id = document_sections.document_id
      and d.owner_id = (select auth.uid())
  ))
  with check (exists (
    select 1 from public.documents d
    where d.id = document_sections.document_id
      and d.owner_id = (select auth.uid())
  ));

 drop policy if exists "Users can delete sections in their own documents" on public.document_sections;
create policy "Users can delete sections in their own documents"
  on public.document_sections for delete to authenticated
  using (exists (
    select 1 from public.documents d
    where d.id = document_sections.document_id
      and d.owner_id = (select auth.uid())
  ));

grant select, insert, update, delete on public.documents to authenticated;
grant select, insert, update, delete on public.document_sections to authenticated;

create or replace function public.match_document_sections(
  query_embedding extensions.vector(384),
  match_count integer
)
returns table (
  id bigint,
  content text,
  similarity real
)
language sql
stable
security invoker
set search_path = public, extensions
as $$
  select
    s.id,
    s.content,
    (1 - (s.embedding <=> query_embedding))::real as similarity
  from public.document_sections s
  where s.embedding is not null
    and (select auth.uid()) is not null
  order by s.embedding <=> query_embedding
  limit least(greatest(coalesce(match_count, 5), 1), 50);
$$;

revoke execute on function public.match_document_sections(extensions.vector(384), integer) from public, anon;
grant execute on function public.match_document_sections(extensions.vector(384), integer) to authenticated;"
}

